CASH_W = 0.000767
N_S1 = 105          # rebalances 2023-01-01 .. 2024-12-29
BPS = 10


def path(e, r):
    e = np.asarray(e); r = np.asarray(r)
    de = np.abs(np.diff(np.concatenate([[0.0], e])))
    ret = e * r + (1 - e) * CASH_W - de * BPS / 1e4
    nav = np.cumprod(1 + ret)
    dd = (nav / np.maximum.accumulate(np.maximum(nav, 1.0)) - 1).min()
    sh = ret.mean() / ret.std(ddof=1) * np.sqrt(52)
    return nav[-1] - 1, dd, sh


def block_perm(T, rng, b=4):
    nb = T // b
    order = rng.permutation(nb)
    idx = np.concatenate([np.arange(p * b, (p + 1) * b) for p in order])
    return np.concatenate([idx, np.arange(nb * b, T)]).astype(int)


def run(name, R, trials=2000, seed=20261014):
    assert len(R) == len(E) == 197, (len(R), len(E))
    rng = np.random.default_rng(seed)
    out = {}
    for seg, sl in (("S1", slice(0, N_S1)), ("S2", slice(N_S1, 197))):
        e = np.asarray(E[sl]); r = np.asarray(R[sl])
        m = path(e, r)
        a = path(np.full_like(e, e.mean()), r)
        full = path(np.ones_like(e), r)
        tots = np.array([path(e[block_perm(len(e), rng)], r)[0] for _ in range(trials)])
        dds = np.array([path(e[block_perm(len(e), rng)], r)[1] for _ in range(trials)])
        out[seg] = dict(main=m, A=a, full=full, ebar=e.mean(),
                        B_p50=np.percentile(tots, 50), B_p90=np.percentile(tots, 90), B_p95=np.percentile(tots, 95),
                        pct_main=(tots < m[0]).mean(), B_dd_p50=np.percentile(dds, 50), pct_dd=(dds < m[1]).mean())
    print(f"== {name}")
    for seg, o in out.items():
        f = lambda t: f"{t[0]*100:+.1f}% / DD {t[1]*100:.1f}% / Sh {t[2]:.2f}"
        print(f"  {seg} ē={o['ebar']:.2f}  main {f(o['main'])} | A {f(o['A'])} | full {f(o['full'])}")
        print(f"      B total p50 {o['B_p50']*100:+.1f}% p90 {o['B_p90']*100:+.1f}% p95 {o['B_p95']*100:+.1f}% → main pct {o['pct_main']:.3f};"
              f"  B DD p50 {o['B_dd_p50']*100:.1f}% → main DD better than {1-o['pct_dd']:.3f} of shuffles")
    return out


if __name__ == "__main__":
    run("top-50 cap-weighted (M-557 main arm)", R_CAP)
    run("BTC with breadth exposure", R_BTC)
